import 'package:flutter/material.dart';

/// A viva topic groups related questions into 3 progressive stages (Foundation →
/// Intermediate → Advanced), backing the stage-map UI in the Viva Examiner.
class VivaTopic {
  final String id;
  final String name;
  final IconData icon;
  final String description;
  const VivaTopic({required this.id, required this.name, required this.icon, required this.description});
}

const List<VivaTopic> vivaTopics = [
  VivaTopic(id: 'mendelian', name: 'Mendelian Genetics', icon: Icons.science, description: 'Segregation, dominance, and classic cross ratios.'),
  VivaTopic(id: 'quantitative', name: 'Quantitative Genetics', icon: Icons.query_stats, description: 'Heritability, variance components, and genetic advance.'),
  VivaTopic(id: 'breeding-methods', name: 'Breeding Methods', icon: Icons.alt_route, description: 'Pedigree, backcross, hybrid, and modern selection methods.'),
  VivaTopic(id: 'molecular-markers', name: 'Molecular Markers & MAS', icon: Icons.biotech, description: 'DNA markers, marker-assisted and genomic selection.'),
  VivaTopic(id: 'genomics', name: 'QTL, GWAS & Genomic Selection', icon: Icons.scatter_plot, description: 'Mapping populations, association studies, and prediction.'),
];

/// 1 = Foundation, 2 = Intermediate, 3 = Advanced.
class VivaQuestion {
  final String id;
  final String topicId;
  final int stage;
  final String question;
  final List<String> options;
  final int correctIndex;
  final String followUpCorrect;
  final String followUpIncorrect;

  const VivaQuestion({
    required this.id,
    required this.topicId,
    required this.stage,
    required this.question,
    required this.options,
    required this.correctIndex,
    required this.followUpCorrect,
    required this.followUpIncorrect,
  });
}

