  VivaQuestion(id: 'mol-i2', topicId: 'molecular-markers', stage: 2, question: 'In marker-assisted backcrossing, selecting for the target gene itself is "foreground selection," while selecting markers spread across the rest of the genome to speed recurrent-parent recovery is called:', options: ['Background selection', 'Positional selection', 'Tandem selection', 'Divergent selection'], correctIndex: 0, followUpCorrect: 'Correct. How many fewer backcross generations can background selection save compared to relying on backcrossing alone?', followUpIncorrect: 'Foreground = the target gene. What would you call selection for everything else, in the "background" of the genome?'),
  VivaQuestion(id: 'mol-i3', topicId: 'molecular-markers', stage: 2, question: 'Compared to older RFLP markers, SNP markers are generally preferred in modern breeding because they are:', options: ['Rarer in the genome', 'More abundant and cheaper to genotype at high throughput', 'Only usable in animals', 'Impossible to automate'], correctIndex: 1, followUpCorrect: 'Right. How does high marker density help increase mapping resolution?', followUpIncorrect: 'Think about genome-wide abundance and genotyping cost — which of these favors SNPs over RFLPs at scale?'),
