  VivaQuestion(id: 'gen-f3', topicId: 'genomics', stage: 1, question: 'A higher LOD score at a marker in QTL mapping generally indicates:', options: ['Weaker statistical support for a QTL nearby', 'Stronger statistical support for a QTL nearby', 'A genotyping error', 'Lower marker density'], correctIndex: 1, followUpCorrect: 'Right. What LOD score threshold is conventionally used as a significance cutoff in QTL mapping?', followUpIncorrect: 'LOD stands for "logarithm of odds" in favor of linkage — higher values mean stronger, not weaker, evidence.'),
